  '0001_catalog.sql': '-- Selling territories. Currency and tax live here, not on the product.\nCREATE TABLE regions (\n  id            TEXT    PRIMARY KEY,\n  name          TEXT    NOT NULL,\n  currency_code TEXT    NOT NULL,\n  tax_rate      INTEGER NOT NULL,\n  tax_inclusive INTEGER NOT NULL DEFAULT 0,\n  countries     TEXT    NOT NULL\n);\n\n-- Sellable items. Not buyable themselves; their variants are.\nCREATE TABLE products (\n  id          TEXT PRIMARY KEY,\n  title       TEXT NOT NULL,\n  handle      TEXT NOT NULL UNIQUE,\n  description TEXT,\n  thumbnail   TEXT,\n  status      TEXT NOT NULL DEFAULT \'draft\'\n);\n\n-- The axes a product\'s variants vary along, such as Size.\nCREATE TABLE product_options (\n  id         TEXT PRIMARY KEY,\n  product_id TEXT NOT NULL REFERENCES products (id) ON DELETE CASCADE,\n  title      TEXT NOT NULL,\n  values_csv TEXT NOT NULL\n);\n\n-- The buyable configurations. Stock lives here.\nCREATE TABLE product_variants (\n  id                 TEXT    PRIMARY KEY,\n  product_id         TEXT    NOT NULL REFERENCES products (id) ON DELETE CASCADE,\n  title              TEXT    NOT NULL,\n  sku                TEXT,\n  inventory_quantity INTEGER NOT NULL DEFAULT 0,\n  manage_inventory   INTEGER NOT NULL DEFAULT 1,\n  allow_backorder    INTEGER NOT NULL DEFAULT 0\n);\n\n-- One price per variant per currency. The pair is the key, so a second\n-- price in the same currency cannot be inserted at all.\nCREATE TABLE variant_prices (\n  variant_id    TEXT    NOT NULL REFERENCES product_variants (id) ON DELETE CASCADE,\n  currency_code TEXT    NOT NULL,\n  amount        INTEGER NOT NULL,\n  PRIMARY KEY (variant_id, currency_code)\n);\n\n-- The option values a variant was built from.\nCREATE TABLE variant_option_values (\n  variant_id TEXT NOT NULL REFERENCES product_variants (id) ON DELETE CASCADE,\n  option_id  TEXT NOT NULL REFERENCES product_options (id) ON DELETE CASCADE,\n  value      TEXT NOT NULL,\n  PRIMARY KEY (variant_id, option_id)\n);\n\nCREATE INDEX idx_variants_product ON product_variants (product_id);\nCREATE INDEX idx_options_product ON product_options (product_id);\n',
  '0002_ordering.sql': '-- Buyers. A guest checkout has none of these, only an email on the cart.\nCREATE TABLE customers (\n  id         TEXT PRIMARY KEY,\n  email      TEXT NOT NULL UNIQUE,\n  first_name TEXT,\n  last_name  TEXT,\n  phone      TEXT\n);\n\n-- Carts belong to a region, which fixes their currency and tax rule.\nCREATE TABLE carts (\n  id          TEXT NOT NULL PRIMARY KEY,\n  region_id   TEXT NOT NULL REFERENCES regions (id),\n  customer_id TEXT REFERENCES customers (id),\n  email       TEXT,\n  created_at  TEXT NOT NULL\n);\n\n-- A line snapshots the price and the titles it was added under, so it is\n-- deliberately not a join away from the variant it came from.\nCREATE TABLE line_items (\n  id            TEXT    PRIMARY KEY,\n  cart_id       TEXT    NOT NULL REFERENCES carts (id) ON DELETE CASCADE,\n  variant_id    TEXT    NOT NULL REFERENCES product_variants (id),\n  product_id    TEXT    NOT NULL REFERENCES products (id),\n  title         TEXT    NOT NULL,\n  variant_title TEXT,\n  unit_amount   INTEGER NOT NULL,\n  currency_code TEXT    NOT NULL,\n  quantity      INTEGER NOT NULL CHECK (quantity > 0)\n);\n\n-- A placed order. Totals are stored, never recomputed.\nCREATE TABLE orders (\n  id             TEXT    PRIMARY KEY,\n  region_id      TEXT    NOT NULL REFERENCES regions (id),\n  customer_id    TEXT    REFERENCES customers (id),\n  email          TEXT    NOT NULL,\n  currency_code  TEXT    NOT NULL,\n  subtotal       INTEGER NOT NULL,\n  tax            INTEGER NOT NULL,\n  total          INTEGER NOT NULL,\n  status         TEXT    NOT NULL DEFAULT \'pending\',\n  payment_status TEXT    NOT NULL DEFAULT \'awaiting\',\n  placed_at      TEXT    NOT NULL\n);\n\n-- Order lines are copied from the cart, not shared with it.\nCREATE TABLE order_items (\n  id            TEXT    PRIMARY KEY,\n  order_id      TEXT    NOT NULL REFERENCES orders (id) ON DELETE CASCADE,\n  variant_id    TEXT    NOT NULL,\n  product_id    TEXT    NOT NULL,\n  title         TEXT    NOT NULL,\n  variant_title TEXT,\n  unit_amount   INTEGER NOT NULL,\n  currency_code TEXT    NOT NULL,\n  quantity      INTEGER NOT NULL CHECK (quantity > 0)\n);\n\n-- Addresses are owned by the order they were used for, so editing an\n-- account\'s address later cannot rewrite where something was shipped.\nCREATE TABLE order_addresses (\n  order_id     TEXT NOT NULL REFERENCES orders (id) ON DELETE CASCADE,\n  kind         TEXT NOT NULL CHECK (kind IN (\'shipping\', \'billing\')),\n  first_name   TEXT NOT NULL,\n  last_name    TEXT NOT NULL,\n  line1        TEXT NOT NULL,\n  line2        TEXT,\n  city         TEXT NOT NULL,\n  province     TEXT,\n  postal_code  TEXT NOT NULL,\n  country_code TEXT NOT NULL,\n  phone        TEXT,\n  PRIMARY KEY (order_id, kind)\n);\n\nCREATE INDEX idx_line_items_cart ON line_items (cart_id);\nCREATE INDEX idx_order_items_order ON order_items (order_id);\nCREATE INDEX idx_orders_customer ON orders (customer_id);\nCREATE INDEX idx_orders_email ON orders (email);\n',
  '0003_shipping.sql': '-- What a region offers as a way of getting goods to a customer.\nCREATE TABLE shipping_options (\n  id            TEXT    PRIMARY KEY,\n  region_id     TEXT    NOT NULL REFERENCES regions (id) ON DELETE CASCADE,\n  name          TEXT    NOT NULL,\n  amount        INTEGER NOT NULL CHECK (amount >= 0),\n  currency_code TEXT    NOT NULL\n);\n\nCREATE INDEX idx_shipping_options_region ON shipping_options (region_id);\n\n-- The method a cart chose, with the price and name snapshotted. A cart has at\n-- most one, which is why the cart id is the key rather than a foreign key on a\n-- list table.\nCREATE TABLE cart_shipping_methods (\n  cart_id     TEXT    PRIMARY KEY REFERENCES carts (id) ON DELETE CASCADE,\n  option_id   TEXT    NOT NULL REFERENCES shipping_options (id),\n  name        TEXT    NOT NULL,\n  amount      INTEGER NOT NULL CHECK (amount >= 0)\n);\n\n-- Orders freeze the method the same way they freeze everything else.\nALTER TABLE orders ADD COLUMN shipping_total INTEGER NOT NULL DEFAULT 0;\nALTER TABLE orders ADD COLUMN discount_total INTEGER NOT NULL DEFAULT 0;\nALTER TABLE orders ADD COLUMN shipping_option_id TEXT;\nALTER TABLE orders ADD COLUMN shipping_name TEXT;\n',
